  <div class="mb-2"><label class="form-label" for="aud">الجمهور</label><select class="form-select" id="aud" name="audience"><?php if ($admin): ?><option value="all">الجميع</option><option value="staff">الموظفون</option><option value="students">الطلاب</option><option value="guardians">أولياء الأمور</option><?php endif; ?><option value="section">شعبة محددة</option></select></div>
  <div class="mb-2"><label class="form-label" for="sec">الشعبة</label><select class="form-select" id="sec" name="section_id"><option value="">—</option><?php foreach ($sections as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['grade_name'] . ' / ' . $s['name']) ?></option><?php endforeach; ?></select></div>
