  <?php if (!empty($wa)): ?><div class="form-check mb-2"><input type="hidden" name="send_whatsapp" value="0"><input class="form-check-input" type="checkbox" name="send_whatsapp" value="1" id="wa"><label class="form-check-label" for="wa">إرسال واتساب لأولياء الأمور أيضًا</label></div><?php endif; ?><?php endif; ?><button class="btn btn-primary" type="submit">نشر</button></form></div>
  <div class="col-lg-7"><div class="card-s"><h2 class="h6">الإعلانات المنشورة</h2><?php if (!$items): ?><div class="empty-state">لا توجد إعلانات.</div><?php endif; ?><?php foreach ($items as $a): ?><div class="border-bottom py-2"><div class="d-flex gap-2 align-items-center"><strong><?= e($a['title']) ?></strong><span class="badge text-bg-info"><?= ['all' => 'الجميع', 'staff' => 'الموظفون', 'students' => 'الطلاب', 'guardians' => 'الأولياء', 'section' => e(($a['grade_name'] ?? '') . ' / ' . ($a['section_name'] ?? ''))][$a['audience']] ?></span><small class="text-muted ms-auto" dir="ltr"><?= e($a['published_at']) ?></small>
  <button class="btn btn-sm btn-outline-danger" data-api="<?= url('api/v1/school/announcements/' . (int)$a['id']) ?>" data-method="DELETE" data-confirm="حذف الإعلان؟"><i class="bi bi-trash"></i></button></div><div class="small text-muted" style="white-space:pre-wrap"><?= e(mb_substr($a['body'], 0, 200)) ?></div></div><?php endforeach; ?></div></div></div>
